import json
import hashlib

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def register_user():
    filename = "users.json"

    # Đọc dữ liệu từ tệp JSON nếu tồn tại
    try:
        with open(filename, "r") as file:
            users = json.load(file)
    except FileNotFoundError:
        users = {}

    # Yêu cầu người dùng nhập tên người dùng
    while True:
        username = input("Nhập tên người dùng: ").strip()
        if username in users:
            print("Tên người dùng đã tồn tại. Vui lòng nhập lại.")
        else:
            break

    # Yêu cầu người dùng nhập mật khẩu
    password = input("Nhập mật khẩu: ").strip()
    hashed_password = hash_password(password)

    # Lưu tên người dùng và mật khẩu đã băm vào tệp JSON
    users[username] = hashed_password

    with open(filename, "w") as file:
        json.dump(users, file, indent=4)

    print("Đăng ký thành công!")

# Chạy chương trình
register_user()

